-- Saudi Arabia deep-dive content: page, stats, 3 file_format cards + 1 lifecycle card
-- (the static page's QR-code data-tag list -- a .flow-grid, but of unordered data tags
-- rather than a sequential process, sitting in the file_format section rather than
-- scope_transmission. This is the FIRST country with a lifecycle-style pill card outside
-- scope_transmission -- required a small renderer change in members-worker/src/index.js
-- to call renderLifecycleCardsForSection(..., 'file_format') for fileFormatHtml, mirroring
-- the existing scope_transmission wiring exactly. Also 4 scope_transmission cards (no
-- lifecycle card in that section this time), 7 steps, 1 penalty row + 3 narrative
-- penalties_related cards (both at once, per Belgium/Italy precedent), 1 portal.

INSERT OR IGNORE INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Saudi Arabia';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Centralised clearance (Fatoora)', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. ZATCA wave schedules, technical specifications, and penalty enforcement continue to evolve — confirm current requirements directly on the ZATCA Fatoora portal before building an integration.', 'ZATCA''s rollout is a genuine two-phase model: first everyone had to generate e-invoices, then — much more demandingly — integrate directly with the government in waves by turnover.', 'Phase 2''s technical bar is genuinely high: cryptographic stamping, mandatory Arabic content, and a QR code that packs in nine distinct data tags.', 'Saudi Arabia runs one of the strictest clearance models in this tracker: a B2B invoice without ZATCA''s clearance response simply has no tax effect.', 'Integration is a genuinely multi-stage technical process — budget real time for certificate generation and sandbox testing, not just format mapping.', 'The fine itself is only part of the exposure — prohibited software behaviours carry their own separate scrutiny.' FROM countries WHERE name_en = 'Saudi Arabia';

