INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Cryptographic controls', '[["Signature algorithm", "ECDSA (Elliptic Curve Digital Signature Algorithm)"], ["Credential", "Cryptographic Stamp Identifier (CSID)"], ["Government layer", "ZATCA applies its own stamp using its private key after clearance"]]', 'The chain of trust runs supplier → ZATCA → recipient: your ECDSA signature proves the invoice came from you, and ZATCA''s own stamp on top of that is what actually makes it legally valid.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'file_format' AND dc.sort_order = 1;
