INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'B2B — real-time clearance', '[["Threshold", "Invoices above SAR 1,000"], ["Requirement", "Cleared by ZATCA before delivery to the buyer"], ["If not cleared", "No legal or tax effect"]]', 'This is stricter than Poland''s KSeF or Italy''s SDI in one specific sense — clearance must happen before delivery, not just before the invoice is considered "final."', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
