INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'B2C — near-real-time reporting', '[["Document type", "Simplified Tax Invoice"], ["Deadline", "Reported within 24 hours of issuance"]]', 'Unlike B2B, simplified invoices can be issued to the customer immediately — the 24-hour clock covers reporting to ZATCA, not pre-clearance.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
